package br.ucb.claquete.controller;
import br.ucb.claquete.service.AcervoJdbcService;import java.net.URI;import java.util.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api/avaliacoes")public class AvaliacaoController{private final AcervoJdbcService s;public AvaliacaoController(AcervoJdbcService s){this.s=s;}@GetMapping public List<Map<String,Object>>listar(){return s.avaliacoes();}@GetMapping("/{filmeId}/{usuarioId}")public Map<String,Object>buscar(@PathVariable int filmeId,@PathVariable int usuarioId){return s.avaliacao(filmeId,usuarioId);}@PostMapping public ResponseEntity<Map<String,Object>>criar(@RequestBody Map<String,Object>r){Map<String,Object>x=s.criarAvaliacao(r);return ResponseEntity.created(URI.create("/api/avaliacoes/"+x.get("filmeId")+"/"+x.get("usuarioId"))).body(x);}@PutMapping("/{filmeId}/{usuarioId}")public Map<String,Object>atualizar(@PathVariable int filmeId,@PathVariable int usuarioId,@RequestBody Map<String,Object>r){return s.atualizarAvaliacao(filmeId,usuarioId,r);}@DeleteMapping("/{filmeId}/{usuarioId}")@ResponseStatus(HttpStatus.NO_CONTENT)public void excluir(@PathVariable int filmeId,@PathVariable int usuarioId){s.excluirAvaliacao(filmeId,usuarioId);}}
